#![no_std]
//! A contract that hashes a string and returns the hash

use sha2::Digest;
use hex_literal::hex;

// Generated by `shasum -a 256 src/hash_input`
const EXPECT: [u8; 32] =
    hex!("2cf24dba5fb0a30e26e83b2ac5b9e29e1b161e5c1fa7425e73043362938b9824");

/// The host-side reference for the digest the guest entrypoint returns.
pub fn test_hello() {
    let hash = sha2::Sha256::digest(b"hello");

    assert_eq!(hash.as_ref(), EXPECT);
}

// rv32 dispatches guest-side: a hand-written record registers method id
// u64::MAX outside the #[contract] macro's calldata/Return glue, and the
// wrapper returns the in-guest digest.
#[cfg(target_arch = "riscv32")]
mod rv32_entry {
    use sha2::Digest;

    extern "C" fn hash_and_return() {
        let hash = sha2::Sha256::digest(b"hello");
        assert_eq!(hash.as_ref(), super::EXPECT);
        thruput_sdk::sys::raw_Return(hash.as_ref(), false, &[])
    }

    #[used]
    #[unsafe(link_section = "groundhog_rv32_entrypoints")]
    static HASH_ENTRY: thruput_sdk::__rv32::Entrypoint = thruput_sdk::__rv32::Entrypoint {
        method_id: u64::MAX,
        wrapper: hash_and_return,
    };
}

#[test]
fn test_hash_bug() {
    test_hello();
}
